import java.util.*;

class Solution {
    public boolean matches(String t, String p) {
        int n = t.length(), m = p.length();
        boolean[][] dp = new boolean[n + 1][m + 1];   // dp[i][j]: t[i..] matches p[j..]
        dp[n][m] = true;
        for (int i = n; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                boolean first = i < n && (p.charAt(j) == t.charAt(i) || p.charAt(j) == '.');
                if (j + 1 < m && p.charAt(j + 1) == '*') {
                    // skip "x*" entirely, or let it eat one char and stay on it
                    dp[i][j] = dp[i][j + 2] || (first && dp[i + 1][j]);
                } else {
                    dp[i][j] = first && dp[i + 1][j + 1];
                }
            }
        }
        return dp[0][0];
    }
}

