function matches(t, p) {
  const memo = new Map();
  function go(i, j) {
    const key = i * 100 + j;
    if (memo.has(key)) return memo.get(key);
    let r;
    if (j === p.length) r = i === t.length;
    else {
      const first = i < t.length && (p[j] === t[i] || p[j] === ".");
      if (j + 1 < p.length && p[j+1] === "*") r = go(i, j + 2) || (first && go(i + 1, j));
      else r = first && go(i + 1, j + 1);
    }
    memo.set(key, r);
    return r;
  }
  return go(0, 0);
}
